// OptionalDemo.java
import java.util.Optional;
import java.util.List;
import java.util.ArrayList;
import java.util.NoSuchElementException;

public class OptionalDemo {

    /* --------------------------------------------------------------------- */
    /* Simple domain model --------------------------------------------------- */
    /* --------------------------------------------------------------------- */
    static class User {
        private final String id;
        private final String name;

        User(String id, String name) {
            this.id   = id;
            this.name = name;
        }

        public String getId()   { return id; }
        public String getName() { return name; }

        @Override
        public String toString() {
            return "User{id='" + id + "', name='" + name + "'}";
        }
    }

    /* --------------------------------------------------------------------- */
    /* A toy "repository" that returns Optional<User> ----------------------- */
    /* --------------------------------------------------------------------- */
    static class UserRepository {
        private final List<User> users = new ArrayList<>();

        UserRepository() {
            users.add(new User("1", "Alice"));
            users.add(new User("2", "Bob"));
            // id "3" is intentionally missing to demonstrate an empty Optional
        }

        /** Finds a user by id, or returns Optional.empty() if not found */
        public Optional<User> findById(String id) {
            return users.stream()
                        .filter(u -> u.getId().equals(id))
                        .findFirst();            // returns Optional<User>
        }
    }

    /* --------------------------------------------------------------------- */
    /* Utility methods that work with Optional ------------------------------ */
    /* --------------------------------------------------------------------- */
    /** Prints the user's name if present, otherwise prints a default value */
    static void printUserName(Optional<User> optUser) {
        // 1. Basic check with ifPresent
        optUser.ifPresent(user -> System.out.println("User found: " + user.getName()));

        // 2. ifPresentOrElse (Java 9+)
        optUser.ifPresentOrElse(
                user -> System.out.println("Alternative print: " + user.getName()),
                ()   -> System.out.println("No user found – using default"));

        // 3. orElse / orElseGet
        String name = optUser.map(User::getName)
                             .orElse("Default User");
        System.out.println("Name via orElse: " + name);

        String lazyName = optUser.map(User::getName)
                                 .orElseGet(() -> {
                                     System.out.println("Computing default lazily");
                                     return "Lazy Default";
                                 });
        System.out.println("Name via orElseGet: " + lazyName);

        // 4. orElseThrow
        try {
            User requiredUser = optUser.orElseThrow(
                    () -> new NoSuchElementException("User not found"));
            System.out.println("User via orElseThrow: " + requiredUser);
        } catch (NoSuchElementException ex) {
            System.out.println(ex.getMessage());
        }

        // 5. filter & map example
        String filtered = optUser.filter(u -> u.getName().startsWith("A"))
                                 .map(User::getName)
                                 .orElse("No A-starting user");
        System.out.println("Filtered name: " + filtered);
    }

    /* --------------------------------------------------------------------- */
    /* Main method ----------------------------------------------------------- */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        UserRepository repo = new UserRepository();

        // Example 1: User exists
        Optional<User> alice = repo.findById("1");
        System.out.println("\n--- Looking up user id 1 ---");
        printUserName(alice);

        // Example 2: User does not exist
        Optional<User> unknown = repo.findById("3");
        System.out.println("\n--- Looking up user id 3 (missing) ---");
        printUserName(unknown);

        // Example 3: Using Optional.ofNullable (handles null safely)
        User maybeNullUser = null;            // could come from some API
        Optional<User> optFromNullable = Optional.ofNullable(maybeNullUser);
        System.out.println("\n--- Optional.ofNullable with null ---");
        printUserName(optFromNullable);
    }
}
```

### What the code demonstrates

| Feature | Example |
|---------|---------|
| **Creation** | `Optional.ofNullable(obj)`, `Optional.empty()`, `Optional.of(value)` |
| **Presence checks** | `ifPresent(...)`, `ifPresentOrElse(...)` |
| **Value retrieval** | `orElse(...)`, `orElseGet(...)`, `orElseThrow(...)` |
| **Transformation** | `map(...)`, `filter(...)`, `flatMap(...)` |
| **Chaining** | `opt.map(...).filter(...).orElse(...)` |

Compile and run:

```bash
javac OptionalDemo.java
java OptionalDemo
```

You’ll see how `Optional` eliminates the need for explicit `null` checks while keeping the code concise and expressive.
